  1→package jlsm.table;
  2→
  3→import java.util.Objects;
  4→
  5→/**
  6→ * A document stored in a {@link JlsmTable}, with values ordered according to a {@link JlsmSchema}.
  7→ *
  8→ * <p>
  9→ * Values are stored in schema-field order. A {@code null} entry means the field is absent (PATCH
 10→ * semantics). Type validation is performed eagerly at construction.
 11→ */
 12→public final class JlsmDocument {
 13→
 14→    static {
 15→        jlsm.table.internal.DocumentAccess
 16→                .setAccessor(new jlsm.table.internal.DocumentAccess.Accessor() {
 17→                    @Override
 18→                    public Object[] values(JlsmDocument doc) {
 19→                        return doc.values();
 20→                    }
 21→
 22→                    @Override
 23→                    public JlsmDocument create(jlsm.table.JlsmSchema schema, Object[] values) {
 24→                        return new JlsmDocument(schema, values);
 25→                    }
 26→                });
 27→    }
 28→
 29→    private final JlsmSchema schema;
 30→    private final Object[] values;
 31→
 32→    /**
 33→     * Package-private constructor used by the deserializer.
 34→     *
 35→     * @param schema the schema describing the document structure; must not be null
 36→     * @param values values in schema-field order; must not be null
 37→     */
 38→    JlsmDocument(JlsmSchema schema, Object[] values) {
 39→        assert schema != null : "schema must not be null";
 40→        assert values != null : "values must not be null";
 41→        assert values.length == schema.fields().size() : "values length must match field count";
 42→        this.schema = schema;
 43→        this.values = values;
 44→    }
 45→
 46→    /**
 47→     * Creates a {@link JlsmDocument} from alternating name/value pairs.
 48→     *
 49→     * <p>
 50→     * Fields not mentioned in {@code nameValuePairs} default to {@code null}. Each value is
 51→     * validated against the declared field type; {@code null} is always accepted (absent field).
 52→     *
 53→     * @param schema the schema describing valid fields; must not be null
 54→     * @param nameValuePairs alternating {@code String name, Object value} pairs
 55→     * @return a new JlsmDocument
 56→     * @throws IllegalArgumentException if a field name is unknown, type is mismatched, or pairs
 57→     *             length is odd
 58→     */
 59→    public static JlsmDocument of(JlsmSchema schema, Object... nameValuePairs) {
 60→        Objects.requireNonNull(schema, "schema must not be null");
 61→        assert nameValuePairs != null : "nameValuePairs must not be null";
 62→        if (nameValuePairs.length % 2 != 0) {
 63→            throw new IllegalArgumentException(
 64→                    "nameValuePairs must be an even number of alternating name/value entries");
 65→        }
 66→
 67→        final Object[] values = new Object[schema.fields().size()];
 68→
 69→        for (int i = 0; i < nameValuePairs.length; i += 2) {
 70→            final Object rawName = nameValuePairs[i];
 71→            if (!(rawName instanceof String fieldName)) {
 72→                throw new IllegalArgumentException(
 73→                        "nameValuePairs entry at index " + i + " must be a String field name");
 74→            }
 75→            final int idx = schema.fieldIndex(fieldName);
 76→            if (idx < 0) {
 77→                throw new IllegalArgumentException("Unknown field: '" + fieldName + "'");
 78→            }
 79→            final Object value = nameValuePairs[i + 1];
 80→            if (value != null) {
 81→                validateType(fieldName, schema.fields().get(idx).type(), value);
 82→            }
 83→            values[idx] = value;
 84→        }
 85→
 86→        return new JlsmDocument(schema, values);
 87→    }
 88→
 89→    // -------------------------------------------------------------------------
 90→    // Typed getters
 91→    // -------------------------------------------------------------------------
 92→
 93→    /** Returns the schema for this document. */
 94→    public JlsmSchema schema() {
 95→        return schema;
 96→    }
 97→
 98→    /** Returns the raw value array in schema-field order (package-private for serializer use). */
 99→    Object[] values() {
100→        return values;
101→    }
102→
103→    /** Returns {@code true} if the field with the given name is null/absent. */
104→    public boolean isNull(String field) {
105→        return values[requireIndex(field)] == null;
106→    }
107→
108→    /** Returns the STRING value of the named field. */
109→    public String getString(String field) {
110→        return (String) requireValue(field, FieldType.Primitive.STRING);
111→    }
112→
113→    /** Returns the INT8 value of the named field as a {@code byte}. */
114→    public byte getByte(String field) {
115→        return (Byte) requireValue(field, FieldType.Primitive.INT8);
116→    }
117→
118→    /** Returns the INT16 value of the named field as a {@code short}. */
119→    public short getShort(String field) {
120→        return (Short) requireValue(field, FieldType.Primitive.INT16);
121→    }
122→
123→    /** Returns the INT32 value of the named field as an {@code int}. */
124→    public int getInt(String field) {
125→        return (Integer) requireValue(field, FieldType.Primitive.INT32);
126→    }
127→
128→    /**
129→     * Returns the INT64 or TIMESTAMP value of the named field as a {@code long}.
130→     *
131→     * <p>
132→     * Use {@link #getTimestamp(String)} for TIMESTAMP fields if you want self-documenting code.
133→     */
134→    public long getLong(String field) {
135→        final int idx = requireIndex(field);
136→        final FieldType type = schema.fields().get(idx).type();
137→        if (type != FieldType.Primitive.INT64 && type != FieldType.Primitive.TIMESTAMP) {
138→            throw new IllegalArgumentException(
139→                    "Field '" + field + "' is not INT64 or TIMESTAMP, got " + type);
140→        }
141→        return (Long) values[idx];
142→    }
143→
144→    /** Returns the raw IEEE 754 half-precision bits for the FLOAT16 named field. */
145→    public short getFloat16Bits(String field) {
146→        return (Short) requireValue(field, FieldType.Primitive.FLOAT16);
147→    }
148→
149→    /** Returns the FLOAT32 value of the named field as a {@code float}. */
150→    public float getFloat(String field) {
151→        return (Float) requireValue(field, FieldType.Primitive.FLOAT32);
152→    }
153→
154→    /** Returns the FLOAT64 value of the named field as a {@code double}. */
155→    public double getDouble(String field) {
156→        return (Double) requireValue(field, FieldType.Primitive.FLOAT64);
157→    }
158→
159→    /** Returns the BOOLEAN value of the named field. */
160→    public boolean getBoolean(String field) {
161→        return (Boolean) requireValue(field, FieldType.Primitive.BOOLEAN);
162→    }
163→
164→    /** Returns the TIMESTAMP value of the named field as a UTC epoch millisecond {@code long}. */
165→    public long getTimestamp(String field) {
166→        return (Long) requireValue(field, FieldType.Primitive.TIMESTAMP);
167→    }
168→
169→    /** Returns the ARRAY value of the named field. */
170→    public Object[] getArray(String field) {
171→        final int idx = requireIndex(field);
172→        if (!(schema.fields().get(idx).type() instanceof FieldType.ArrayType)) {
173→            throw new IllegalArgumentException("Field '" + field + "' is not an array type");
174→        }
175→        return (Object[]) values[idx];
176→    }
177→
178→    /** Returns the nested document (ObjectType) value of the named field. */
179→    public JlsmDocument getObject(String field) {
180→        final int idx = requireIndex(field);
181→        if (!(schema.fields().get(idx).type() instanceof FieldType.ObjectType)) {
182→            throw new IllegalArgumentException("Field '" + field + "' is not an object type");
183→        }
184→        return (JlsmDocument) values[idx];
185→    }
186→
187→    // -------------------------------------------------------------------------
188→    // JSON / YAML stubs — filled in by later tasks
189→    // -------------------------------------------------------------------------
190→
191→    /** Serializes this document to a compact JSON string. */
192→    public String toJson() {
193→        return new jlsm.table.internal.JsonWriter().write(this, 0);
194→    }
195→
196→    /**
197→     * Serializes this document to a JSON string.
198→     *
199→     * @param pretty {@code true} for pretty-printed output
200→     */
201→    public String toJson(boolean pretty) {
202→        return new jlsm.table.internal.JsonWriter().write(this, pretty ? 2 : 0);
203→    }
204→
205→    /**
206→     * Deserializes a JSON string into a {@link JlsmDocument} conforming to the given schema.
207→     *
208→     * @param json the JSON string; must not be null
209→     * @param schema the target schema; must not be null
210→     * @return a new JlsmDocument
211→     */
212→    public static JlsmDocument fromJson(String json, JlsmSchema schema) {
213→        return new jlsm.table.internal.JsonParser().parse(json, schema);
214→    }
215→
216→    /** Serializes this document to a YAML block-style string. */
217→    public String toYaml() {
218→        return new jlsm.table.internal.YamlWriter().write(this);
219→    }
220→
221→    /**
222→     * Deserializes a YAML string into a {@link JlsmDocument} conforming to the given schema.
223→     *
224→     * @param yaml the YAML string; must not be null
225→     * @param schema the target schema; must not be null
226→     * @return a new JlsmDocument
227→     */
228→    public static JlsmDocument fromYaml(String yaml, JlsmSchema schema) {
229→        return new jlsm.table.internal.YamlParser().parse(yaml, schema);
230→    }
231→
232→    // -------------------------------------------------------------------------
233→    // Internal helpers
234→    // -------------------------------------------------------------------------
235→
236→    private int requireIndex(String field) {
237→        Objects.requireNonNull(field, "field must not be null");
238→        final int idx = schema.fieldIndex(field);
239→        if (idx < 0) {
240→            throw new IllegalArgumentException("Unknown field: '" + field + "'");
241→        }
242→        return idx;
243→    }
244→
245→    private Object requireValue(String field, FieldType expectedType) {
246→        final int idx = requireIndex(field);
247→        final FieldType actualType = schema.fields().get(idx).type();
248→        if (actualType != expectedType) {
249→            throw new IllegalArgumentException(
250→                    "Field '" + field + "' has type " + actualType + ", not " + expectedType);
251→        }
252→        final Object val = values[idx];
253→        if (val == null) {
254→            throw new NullPointerException("Field '" + field + "' is null");
255→        }
256→        return val;
257→    }
258→
259→    /**
260→     * Validates that {@code value} is compatible with {@code type}.
261→     *
262→     * @param fieldName the field name (for error messages)
263→     * @param type the declared field type
264→     * @param value the non-null value to check
265→     * @throws IllegalArgumentException if the value type does not match
266→     */
267→    private static void validateType(String fieldName, FieldType type, Object value) {
268→        assert fieldName != null : "fieldName must not be null";
269→        assert type != null : "type must not be null";
270→        assert value != null : "value must not be null (nulls are handled by callers)";
271→
272→        switch (type) {
273→            case FieldType.Primitive p -> {
274→                switch (p) {
275→                    case STRING -> expect(fieldName, value, String.class, "STRING");
276→                    case INT8 -> expect(fieldName, value, Byte.class, "INT8");
277→                    case INT16 -> expect(fieldName, value, Short.class, "INT16");
278→                    case INT32 -> expect(fieldName, value, Integer.class, "INT32");
279→                    case INT64 -> expect(fieldName, value, Long.class, "INT64");
280→                    case FLOAT16 -> expect(fieldName, value, Short.class, "FLOAT16");
281→                    case FLOAT32 -> expect(fieldName, value, Float.class, "FLOAT32");
282→                    case FLOAT64 -> expect(fieldName, value, Double.class, "FLOAT64");
283→                    case BOOLEAN -> expect(fieldName, value, Boolean.class, "BOOLEAN");
284→                    case TIMESTAMP -> expect(fieldName, value, Long.class, "TIMESTAMP");
285→                }
286→            }
287→            case FieldType.ArrayType _ -> expect(fieldName, value, Object[].class, "ARRAY");
288→            case FieldType.VectorType vt -> {
289→                if (vt.elementType() == FieldType.Primitive.FLOAT32) {
290→                    expect(fieldName, value, float[].class, "VECTOR(FLOAT32)");
291→                    final float[] fArr = (float[]) value;
292→                    if (fArr.length != vt.dimensions()) {
293→                        throw new IllegalArgumentException("Field '" + fieldName
294→                                + "' expects VECTOR(FLOAT32, " + vt.dimensions() + ") but got "
295→                                + fArr.length + " elements");
296→                    }
297→                } else {
298→                    expect(fieldName, value, short[].class, "VECTOR(FLOAT16)");
299→                    final short[] sArr = (short[]) value;
300→                    if (sArr.length != vt.dimensions()) {
301→                        throw new IllegalArgumentException("Field '" + fieldName
302→                                + "' expects VECTOR(FLOAT16, " + vt.dimensions() + ") but got "
303→                                + sArr.length + " elements");
304→                    }
305→                }
306→            }
307→            case FieldType.ObjectType _ -> expect(fieldName, value, JlsmDocument.class, "OBJECT");
308→        }
309→    }
310→
311→    private static void expect(String fieldName, Object value, Class<?> expectedClass,
312→            String typeName) {
313→        if (!expectedClass.isInstance(value)) {
314→            throw new IllegalArgumentException("Field '" + fieldName + "' expects " + typeName
315→                    + " (" + expectedClass.getSimpleName() + "), got "
316→                    + value.getClass().getSimpleName());
317→        }
318→    }
319→}
