 21→    21→/**
 22→    22→ * Binary serializer for {@link JlsmDocument} values.
 23→    23→ *
 24→    24→ * <p>
 25→    25→ * The binary format consists of a header (schema version, field count, null bitmask, optional
 26→    26→ * boolean bitmask) followed by serialized non-null, non-boolean field values in schema order.
 27→    27→ *
 28→    28→ * <p>
 29→    29→ * Schema versioning: the header stores the write-time field count. On deserialization with a newer
 30→    30→ * schema, only the write-time fields are decoded; additional fields in the current schema are left
 31→    31→ * {@code null}.
 32→    32→ *
 33→    33→ * <p>
 34→    34→ * Contiguous numeric arrays (INT32, INT64, FLOAT32, FLOAT64) use SIMD byte-swap acceleration via
 35→    35→ * {@code jdk.incubator.vector}.
 36→    36→ */
 37→    37→public final class DocumentSerializer {
 38→    38→
 39→    39→    private DocumentSerializer() {
 40→    40→    }
 41→    41→
 42→    42→    /**
 43→    43→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 44→    44→     * schema.
 45→    45→     *
 46→    46→     * @param schema the schema describing the document structure; must not be null
 47→    47→     * @return a MemorySerializer for JlsmDocument
 48→    48→     */
 49→    49→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema) {
 50→    50→        Objects.requireNonNull(schema, "schema must not be null");
 51→    51→        return new SchemaSerializer(schema, /* keyHolder= */ null);
 52→    52→    }
 53→    53→
 54→    54→    /**
 55→    55→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 56→    56→     * schema, with optional field-level encryption.
 57→    57→     *
 58→    58→     * @param schema the schema describing the document structure; must not be null
 59→    59→     * @param keyHolder the key holder for encryption; may be null (no encryption)
 60→    60→     * @return a MemorySerializer for JlsmDocument
 61→    61→     */
 62→    62→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema,
 63→    63→            EncryptionKeyHolder keyHolder) {
 64→    64→        Objects.requireNonNull(schema, "schema must not be null");
 65→    65→        return new SchemaSerializer(schema, keyHolder);
 66→    66→    }
