 68→    68→    // =========================================================================
 69→    69→    // Implementation
 70→    70→    // =========================================================================
 71→    71→
 72→    72→    /** SIMD species for byte-level operations (used for byte-swap shuffles). */
 73→    73→    private static final VectorSpecies<Byte> BYTE_SPECIES = ByteVector.SPECIES_PREFERRED;
 74→    74→
 75→    75→    /** Byte-swap shuffle for INT32 / FLOAT32 (4-byte elements). */
 76→    76→    private static final VectorShuffle<Byte> BSWAP32;
 77→    77→
 78→    78→    /** Byte-swap shuffle for INT64 / FLOAT64 (8-byte elements). */
 79→    79→    private static final VectorShuffle<Byte> BSWAP64;
 80→    80→
 81→    81→    static {
 82→    82→        final int byteLen = BYTE_SPECIES.length();
 83→    83→        final int[] idx32 = new int[byteLen];
 84→    84→        final int[] idx64 = new int[byteLen];
 85→    85→        for (int i = 0; i + 3 < byteLen; i += 4) {
 86→    86→            idx32[i + 0] = i + 3;
 87→    87→            idx32[i + 1] = i + 2;
 88→    88→            idx32[i + 2] = i + 1;
 89→    89→            idx32[i + 3] = i + 0;
 90→    90→        }
 91→    91→        for (int i = 0; i + 7 < byteLen; i += 8) {
 92→    92→            idx64[i + 0] = i + 7;
 93→    93→            idx64[i + 1] = i + 6;
 94→    94→            idx64[i + 2] = i + 5;
 95→    95→            idx64[i + 3] = i + 4;
 96→    96→            idx64[i + 4] = i + 3;
 97→    97→            idx64[i + 5] = i + 2;
 98→    98→            idx64[i + 6] = i + 1;
 99→    99→            idx64[i + 7] = i + 0;
100→   100→        }
101→   101→        BSWAP32 = VectorShuffle.fromArray(BYTE_SPECIES, idx32, 0);
102→   102→        BSWAP64 = VectorShuffle.fromArray(BYTE_SPECIES, idx64, 0);
103→   103→    }
