106→   106→    // Serializer implementation
107→   107→    // -------------------------------------------------------------------------
108→   108→
109→   109→    /** Decodes a single non-boolean, non-null field from a byte array at the cursor position. */
110→   110→    @FunctionalInterface
111→   111→    private interface FieldDecoder {
112→   112→        Object decode(byte[] buf, Cursor cursor);
113→   113→    }
