115→   115→    private static final class SchemaSerializer implements MemorySerializer<JlsmDocument> {
116→   116→
117→   117→        private final JlsmSchema schema;
118→   118→        private final boolean[] isBoolField;
119→   119→        private final int[] prefixBoolCount;
120→   120→        private final int fieldCount;
121→   121→        private final int boolCount;
122→   122→        private final int nullMaskBytes;
123→   123→        private final int boolMaskBytes;
124→   124→        private final FieldDecoder[] decoders;
125→   125→        private final FieldEncryptionDispatch encryptionDispatch;
126→   126→
127→   127→        SchemaSerializer(JlsmSchema schema, EncryptionKeyHolder keyHolder) {
128→   128→            this.schema = schema;
129→   129→
130→   130→            final List<FieldDefinition> fields = schema.fields();
131→   131→            this.fieldCount = fields.size();
132→   132→            final FieldDefinition[] fieldArray = fields.toArray(new FieldDefinition[0]);
133→   133→
134→   134→            // Precompute boolean field flags and prefix counts
135→   135→            this.isBoolField = new boolean[fieldCount];
136→   136→            this.prefixBoolCount = new int[fieldCount + 1];
137→   137→            int bools = 0;
138→   138→            for (int i = 0; i < fieldCount; i++) {
139→   139→                prefixBoolCount[i] = bools;
140→   140→                if (fieldArray[i].type() == FieldType.Primitive.BOOLEAN) {
141→   141→                    isBoolField[i] = true;
142→   142→                    bools++;
143→   143→                }
144→   144→            }
145→   145→            prefixBoolCount[fieldCount] = bools;
146→   146→            this.boolCount = bools;
147→   147→
148→   148→            this.nullMaskBytes = (fieldCount + 7) / 8;
149→   149→            this.boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
