 16→
 17→    // ── Capability query methods ──────────────────────────────────────────────
 18→
 19→    /** Returns {@code true} if equality comparisons are supported on encrypted values. */
 20→    default boolean supportsEquality() {
 21→        return false;
 22→    }
 23→
 24→    /** Returns {@code true} if range (ordering) queries are supported on encrypted values. */
 25→    default boolean supportsRange() {
 26→        return false;
 27→    }
 28→
 29→    /** Returns {@code true} if keyword (single-term) search is supported on encrypted values. */
 30→    default boolean supportsKeywordSearch() {
 31→        return false;
 32→    }
 33→
 34→    /** Returns {@code true} if phrase / proximity search is supported on encrypted values. */
 35→    default boolean supportsPhraseSearch() {
 36→        return false;
 37→    }
 38→
 39→    /** Returns {@code true} if SSE-based encrypted index search is supported. */
 40→    default boolean supportsSseSearch() {
 41→        return false;
 42→    }
 43→
 44→    /**
 45→     * Returns {@code true} if approximate nearest-neighbor search is supported on encrypted values.
 46→     */
 47→    default boolean supportsANN() {
 48→        return false;
 49→    }
 50→
 51→    // ── Permits ───────────────────────────────────────────────────────────────
 52→
 53→    /**
 54→     * No encryption — field values are stored in plaintext. All capabilities are trivially
 55→     * supported (delegated to the underlying index).
 56→     */
 57→    record None() implements EncryptionSpec {
 58→        @Override
 59→        public boolean supportsEquality() {
 60→            return true;
 61→        }
 62→
 63→        @Override
 64→        public boolean supportsRange() {
 65→            return true;
 66→        }
 67→
 68→        @Override
 69→        public boolean supportsKeywordSearch() {
 70→            return true;
 71→        }
 72→
 73→        @Override
 74→        public boolean supportsPhraseSearch() {
