164→   164→        @Override
165→   165→        public MemorySegment serialize(JlsmDocument doc) {
166→   166→            Objects.requireNonNull(doc, "doc must not be null");
167→   167→            assert doc.schema() == schema || doc.schema().name().equals(schema.name())
168→   168→                    : "document schema mismatch";
169→   169→
170→   170→            final List<FieldDefinition> fields = schema.fields();
171→   171→            final int fieldCount = fields.size();
172→   172→            final Object[] values = doc.values();
173→   173→
174→   174→            // Count boolean fields
175→   175→            final int boolCount = countBoolFields(fields);
176→   176→
177→   177→            // Header size: 2 (version) + 2 (fieldCount) + ceil(fieldCount/8) (null mask)
178→   178→            // + (boolCount > 0 ? ceil(boolCount/8) : 0) (bool mask)
179→   179→            final int nullMaskBytes = (fieldCount + 7) / 8;
180→   180→            final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
181→   181→            final int headerSize = 2 + 2 + nullMaskBytes + boolMaskBytes;
182→   182→
183→   183→            // Pre-encrypt fields that have encryptors to determine actual payload size.
184→   184→            // encryptedPayloads[i] holds the ciphertext for encrypted fields, null otherwise.
185→   185→            final byte[][] encryptedPayloads = new byte[fieldCount][];
186→   186→            boolean hasEncryptedFields = false;
187→   187→            for (int i = 0; i < fieldCount; i++) {
188→   188→                final Object val = values[i];
189→   189→                if (val == null || isBoolField[i]) {
190→   190→                    continue;
191→   191→                }
192→   192→                final FieldEncryptionDispatch.FieldEncryptor enc = encryptionDispatch
193→   193→                        .encryptorFor(i);
194→   194→                if (enc != null) {
195→   195→                    // Serialize the field value to a temporary buffer, then encrypt
196→   196→                    final byte[] plainBytes = serializeFieldToBytes(fields.get(i).type(), val);
197→   197→                    encryptedPayloads[i] = enc.encrypt(plainBytes);
198→   198→                    hasEncryptedFields = true;
199→   199→                }
200→   200→            }
201→   201→
202→   202→            // Two-pass: measure then encode
203→   203→            final int payloadSize;
204→   204→            if (!hasEncryptedFields) {
205→   205→                payloadSize = measureFields(fields, values);
206→   206→            } else {
207→   207→                payloadSize = measureFieldsWithEncryption(fields, values, encryptedPayloads);
208→   208→            }
209→   209→            final int totalSize = headerSize + payloadSize;
210→   210→
211→   211→            final byte[] buf = new byte[totalSize];
212→   212→
213→   213→            // Write header
214→   214→            writeShortBE(buf, 0, (short) schema.version());
215→   215→            writeShortBE(buf, 2, (short) fieldCount);
216→   216→            // Null bitmask
217→   217→            buildNullMask(fields, values, buf, 4);
218→   218→            // Boolean bitmask
219→   219→            if (boolCount > 0) {
220→   220→                buildBoolMask(fields, values, buf, 4 + nullMaskBytes);
221→   221→            }
222→   222→
223→   223→            // Write values
224→   224→            final Cursor cursor = new Cursor(buf, headerSize);
225→   225→            if (!hasEncryptedFields) {
226→   226→                encodeFields(fields, values, cursor);
227→   227→            } else {
228→   228→                encodeFieldsWithEncryption(fields, values, encryptedPayloads, cursor);
229→   229→            }
230→   230→
231→   231→            assert cursor.pos == totalSize : "cursor.pos should equal totalSize";
232→   232→            return MemorySegment.ofArray(buf);
233→   233→        }
234→   234→
235→   235→        @Override
236→   236→        public JlsmDocument deserialize(MemorySegment segment) {
237→   237→            Objects.requireNonNull(segment, "segment must not be null");
238→   238→
239→   239→            final ByteArrayView view = extractBytes(segment);
240→   240→            final byte[] buf = view.data();
241→   241→            final Cursor cursor = new Cursor(buf, view.offset());
242→   242→
243→   243→            // Read header
244→   244→            final int _ = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
245→   245→            final int writeFieldCount = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
246→   246→
247→   247→            // We only read min(writeFieldCount, currentFieldCount) fields
248→   248→            final int readCount = Math.min(writeFieldCount, fieldCount);
249→   249→
250→   250→            // Use precomputed prefixBoolCount for O(1) lookup instead of O(n) iteration
251→   251→            final int writeBoolCount = prefixBoolCount[readCount];
252→   252→            final int writeNullMaskBytes = (writeFieldCount + 7) / 8;
253→   253→            final int writeBoolMaskBytes = writeBoolCount > 0 ? (writeBoolCount + 7) / 8 : 0;
254→   254→
255→   255→            final int nullMaskOffset = cursor.advance(writeNullMaskBytes);
256→   256→            final int boolMaskOffset = writeBoolCount > 0 ? cursor.advance(writeBoolMaskBytes) : -1;
257→   257→
258→   258→            // Decode values
259→   259→            final Object[] values = new Object[fieldCount];
260→   260→            // Fields beyond readCount remain null (new fields added in a later schema version)
261→   261→
262→   262→            int boolIdx = 0;
263→   263→            for (int i = 0; i < readCount; i++) {
264→   264→                final boolean isNull = isNullBit(buf, nullMaskOffset, i);
265→   265→                if (isNull) {
266→   266→                    if (isBoolField[i]) {
267→   267→                        boolIdx++;
268→   268→                    }
269→   269→                    continue;
270→   270→                }
271→   271→                if (isBoolField[i]) {
272→   272→                    assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
273→   273→                    values[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
274→   274→                    boolIdx++;
275→   275→                } else {
276→   276→                    final FieldEncryptionDispatch.FieldDecryptor dec = encryptionDispatch
277→   277→                            .decryptorFor(i);
278→   278→                    if (dec != null) {
279→   279→                        // Read length-prefixed encrypted blob, decrypt, then decode
280→   280→                        final int encLen = readVarInt(buf, cursor);
281→   281→                        final byte[] ciphertext = new byte[encLen];
282→   282→                        System.arraycopy(buf, cursor.pos, ciphertext, 0, encLen);
283→   283→                        cursor.pos += encLen;
284→   284→                        final byte[] plainBytes = dec.decrypt(ciphertext);
285→   285→                        final Cursor plainCursor = new Cursor(plainBytes, 0);
286→   286→                        values[i] = decoders[i].decode(plainBytes, plainCursor);
287→   287→                    } else {
288→   288→                        values[i] = decoders[i].decode(buf, cursor);
289→   289→                    }
290→   290→                }
291→   291→            }
292→   292→
293→   293→            return new JlsmDocument(schema, values);
294→   294→        }
295→   295→    }
296→   296→
297→   297→    // =========================================================================
298→   298→    // Measure helpers (first pass)
299→   299→    // =========================================================================
300→   300→
301→   301→    private static int measureFields(List<FieldDefinition> fields, Object[] values) {
302→   302→        int total = 0;
303→   303→        for (int i = 0; i < fields.size(); i++) {
304→   304→            final FieldDefinition fd = fields.get(i);
305→   305→            final Object val = values[i];
306→   306→            if (val == null) {
307→   307→                continue; // null → no value bytes
308→   308→            }
309→   309→            total += measureField(fd.type(), val);
310→   310→        }
311→   311→        return total;
312→   312→    }
313→   313→
314→   314→    private static int measureField(FieldType type, Object value) {
315→   315→        return switch (type) {
316→   316→            case FieldType.Primitive p -> switch (p) {
317→   317→                case STRING -> {
318→   318→                    final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
319→   319→                    yield varIntSize(utf8.length) + utf8.length;
320→   320→                }
321→   321→                case INT8 -> 1;
322→   322→                case INT16 -> 2;
323→   323→                case INT32 -> 4;
324→   324→                case INT64 -> 8;
325→   325→                case FLOAT16 -> 2;
326→   326→                case FLOAT32 -> 4;
327→   327→                case FLOAT64 -> 8;
328→   328→                case BOOLEAN -> 0; // packed in bitmask
329→   329→                case TIMESTAMP -> 8;
330→   330→            };
331→   331→            case FieldType.ArrayType at -> {
332→   332→                final Object[] arr = (Object[]) value;
333→   333→                int sz = varIntSize(arr.length);
334→   334→                for (Object elem : arr) {
335→   335→                    sz += (elem == null) ? 0 : measureField(at.elementType(), elem);
336→   336→                }
337→   337→                yield sz;
338→   338→            }
339→   339→            case FieldType.VectorType vt -> {
340→   340→                final int elemBytes = vt.elementType() == FieldType.Primitive.FLOAT32 ? 4 : 2;
341→   341→                yield vt.dimensions() * elemBytes;
342→   342→            }
343→   343→            case FieldType.ObjectType ot -> {
344→   344→                final JlsmDocument sub = (JlsmDocument) value;
345→   345→                final List<FieldDefinition> subFields = ot.fields();
346→   346→                final int subBoolCount = countBoolFields(subFields);
347→   347→                final int subNullBytes = (subFields.size() + 7) / 8;
348→   348→                final int subBoolBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
349→   349→                int sz = subNullBytes + subBoolBytes;

